INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1157, 18, 'activity', 'owner', NULL, 'title', '2026-10-19 02:31:04.509174+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Arabic line height on Android: the gaps the owner sees on glass"}, "from": {"value": "#140 Arabic line height on Android: the gaps the owner sees on glass"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1158, 18, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:04.509174+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "OWNER REPORT 2026-10-18 (evening): comparing the phones under Arabic, every Arabic surface on the 3T sits taller than the iPhone - the owner''s named sites: the gap between the Arabic prayer name above the countdown and the countdown itself (big on Android, tight on iPhone), the gap between the location and the date on BOTH schedules (Standard and Extras), and the gap between the bottom sheet''s title and its subheading. Wording, lettering and clipping are perfect everywhere - only the spacing differs. This is row 137''s measured ground revisited on the live app: the same TTF renders a taller effective line box on Android by platform design (Rubik''s divergent metric sets, hhea/typo 1.185em against usWin 1.532em and bbox 1.55 to 1.58em; Android derives its box from the taller set), and NO spacing code has landed since (verified from git; row 137 changed no code, no negative pulling). THE TICKET: heavily investigate the gaps the owner names on glass - measure each surface''s rendered line box and inter-element gap on both phones, attribute each gap to the platform line box or to the layout, and bring options with numbers: accepting the platform box (row 87''s law unchanged) or pinning an ar lineHeight per surface family (row 137''s option 2, the owner''s dial, no negative pulling). Investigation and recommendation only before the owner''s ruling; no code\n\nStatus note: 2026-10-18, OWNER REPORT NOT PLANNED 2026-10-18, OWNER REPORT; row 137 FOLDED HERE 2026-10-18 by the owner''s order: its parity verdict and numbers are this row''s ground (the taller Android line box is the standing explanation; the per-surface gap measurements decide what the pinning option would touch), and the owner''s ruling - accept the platform box or pin an ar lineHeight per surface family - lands at this row''s close. HEAVY INVESTIGATION, measurement and options only, no code before the owner''s ruling"}}', NULL);
