INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1290, 63, 'activity', 'owner', NULL, 'title', '2026-10-19 02:31:05.153371+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "The D59 relaunch starves: the in-process reload silently skips most direction-change crossings"}, "from": {"value": "#78 The D59 relaunch starves: the in-process reload silently skips most direction-change crossings"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1291, 63, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:05.153371+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Found by ticket 71''s device step (2026-10-13, 3T mock 2.0.190, production package id): of six crossings in three processes, three reloaded with the textbook cycle and three starved silently - face flips, preference stores, then no convergence dequeue line, no `LANGUAGE:` warn, no `Updates state change: Restart`, no exception, no marker, no FATAL; the app ticks on in the new locale (observed past four minutes), and the once-per-process launch init fired over four minutes late in the drive 3 post-mortem. Row 68''s record states every crossing reloads; the evidence is preserved under sessions/71/ and summarized in 71''s FINDINGS section 8 (D91). This row asks what the reload''s real firing condition is (the commit''s convergence await, the launch-init latch, the direction branch) and fixes it if a repo-side cause exists; device work on the 3T, mock build\n\nStatus note: 2026-10-14, audited: the firing condition pinned and fixed - the commit''s convergence await blocked unbounded and unlogged on the scheduling queue, so a pass grinding at 15 s per silent native call starved the relaunch silently (3 of 6 crossings, 71''s D91 evidence; the missing dequeue line is the discriminator); the direction branch computes true on both crossing directions and the native chain is cleared (no Updates Restart event in the starved logs proves reloadAsync was never reached; on this build the disabled-updates procedure logs Restart before any restart); the launch-init latch is the aggravator (it resets per JS context, so every reload re-runs an unconditionally reopened full notification refresh ahead of the next crossing) and stays untouched with the scheduling paths (ask-first ground). The fix bounds the boundary-crossing wait at 10 s, warns, and relaunches anyway; forward-only convergence heals in the next context (R3.4). Red-first suite stores/__tests__/rtlReloadBound.test.ts with a mutation pass; device work waived by the owner''s run order 2026-10-14, the starvation reproduced unit-side"}}', NULL);
